#include <stdio.h>

int main(){
    int garden[2][4];
    int count = 0;

    garden[0][0] = 1;
    garden[0][1] = 0;
    garden[0][2] = 0;
    garden[0][3] = 1;
    garden[0][4] = 1;

    garden[1][0] = 1;
    garden[1][1] = 0;
    garden[1][2] = 0;
    garden[1][3] = 0;
    garden[1][4] = 1;

    for(int i = 0; i < garden; i++){
        for(int j = 0; j < garden[i]; j++){
            if(garden[i][j] == 0){
                bool GF = true;

                if(i > 0 && garden[i-1][j] == 1){GF = false;}
                if(i < garden -1 && garden[i+1][j] == 1){GF = false;}
                if(j > 0 && garden[i][j-1] == 1){GF == false;}
                if(j < garden[i] -1 && garden[i][j+1] == 1){GF = false;}
                if(GF){count++;}
            }
        }
    }

    printf("Hay %d cuadrados disponibles para plantar.\n", count);
    return 0;
}
